/-- Armsupport: the displayed mathematical construction or bound. This statement assumes [the law parameter](hyp:law), [the L parameter](hyp:L). [This is the stated defined object](goal). -/
def ArmSupport (law : ObservedLaw) (L : ℝ) : Prop :=
  ∀ a : Bool, ∀ᵐ x ∂design, law.Q a x {y | y=0 ∨ y = -L ∨ y=L}=1

/-- [Baseline cap](goal). \(\|m_{0,P}\|_\infty\le1/2\) This statement assumes [the law parameter](hyp:law). -/
-- @node: ass:baseline-cap
def BaselineCap : Prop := ∀ x, |law.m0 x| ≤ 1/2 -- @realizes mzero(supremum cap)

/-- [Baseline smoothness](goal). \(\mathcal G_{0,P}\in\{[g]_\lambda:g\in\mathcal H^\beta(20)\}\). This statement assumes [the v parameter](hyp:v), [the law parameter](hyp:law). -/
-- @node: ass:baseline-smoothness
def BaselineSmooth : Prop := holderBall v.β law.m0 -- @realizes mzero(Holder beta)

/-- [Effect cap](goal). \(\|\tau_P\|_\infty\le1/2\) This statement assumes [the law parameter](hyp:law). -/
-- @node: ass:effect-cap
def EffectCap : Prop := ∀ x, |law.tau x| ≤ 1/2 -- @realizes tau(supremum cap)

/-- [Effect smoothness](goal). \(\mathcal G_{1,P}\in\{[m_{0,P}+t]_\lambda:t\in\mathcal H^\gamma(20)\}\). This statement assumes [the v parameter](hyp:v), [the law parameter](hyp:law). -/
-- @node: ass:effect-smoothness
def EffectSmooth : Prop := holderBall v.γ law.tau -- @realizes tau(Holder gamma)

/-- Legalityranks: the displayed mathematical construction or bound. This statement assumes [the v parameter](hyp:v), [the K parameter](hyp:K), [the M parameter](hyp:M). [This is the stated defined object](goal). -/
def LegalityRanks (v : Params) (K M : ℕ) : Prop :=
  (∃ k, K=2^k) ∧ (∃ m, M=2^m) ∧ 16*M ≤ K ∧ 2 ≤ M ∧ (M:ℝ) ≤ (K:ℝ)^(sumReg v/v.γ)

/-- [Null constancy](goal). \(\exists c\in[-1/2,1/2]\ \forall x\in[0,1],\ \tau_P(x)=c\) This statement assumes [the law parameter](hyp:law). -/
-- @node: ass:null-constancy
def NullConstancy : Prop := ∃ c : ℝ, -1/2 ≤ c ∧ c ≤ 1/2 ∧ ∀ x, law.tau x = c -- @realizes c(candidate constant in [-1/2,1/2])

/-- [Overlap](goal). \(e_P([0,1])\subseteq[1/4,3/4]\) This statement assumes [the law parameter](hyp:law). -/
-- @node: ass:overlap
def Overlap : Prop := ∀ x, 1/4 ≤ law.e x ∧ law.e x ≤ 3/4 -- @realizes e(fixed overlap envelope)

/-- Every positive-weight law belongs to the specified class. This statement assumes [the π parameter](hyp:π), [the C parameter](hyp:C). [This is the stated defined object](goal). -/
def PriorSupported (π : FinitePrior) (C : Set ObservedLaw) : Prop :=
  ∀ i, 0 < priorWeight π i → priorLaw π i ∈ C

/-- [Propensity smoothness](goal). \(\mathcal E_P\in\{[f]_\lambda:f\in\mathcal H^\alpha(20)\}\). This statement assumes [the v parameter](hyp:v), [the law parameter](hyp:law). -/
-- @node: ass:propensity-smoothness
def PropensitySmooth : Prop := holderBall v.α law.e -- @realizes e(Holder alpha)

/-- [Uniform](goal). \(P_X=\lambda\) This statement assumes [the law parameter](hyp:law). -/
-- @node: ass:uniform
def UniformDesign : Prop := covariateLaw law = design -- @realizes PX(uniform marginal) @realizes lambda(known marginal)

/-- The first conditional activity is the sum of component even chi-square activities. This statement assumes [the n parameter](hyp:n), [the K parameter](hyp:K), [the M parameter](hyp:M), [the a parameter](hyp:a), [the u parameter](hyp:u), [the aug parameter](hyp:aug). [This is the stated defined object](goal). -/
def activityA (n K M : ℕ) (a u : ℝ) (aug : Augmentation n K) : ℝ :=
  ∑ C ∈ components n K M aug, componentEvenActivity n K M a u aug C

/-- Recover original records by forgetting disclosure and the unused zero-mark sign. This statement assumes [the n parameter](hyp:n), [the K parameter](hyp:K), [the L parameter](hyp:L), [the z parameter](hyp:z). [This is the stated defined object](goal). -/
def augmentedObserve (n K : ℕ) (L : ℝ) (z : Augmentation n K × Labels n) : Dataset n :=
  fun i => (z.1.1 i,(z.2 i).1,if z.1.2.1 i then signVal (z.2 i).2*L else 0)

/-- The intermediate component density averages both values of its undisclosed coarse sign. This statement assumes [the n parameter](hyp:n), [the K parameter](hyp:K), [the M parameter](hyp:M), [the a parameter](hyp:a), [the u parameter](hyp:u), [the aug parameter](hyp:aug), [the C parameter](hyp:C), [the labels parameter](hyp:labels). [This is the stated defined object](goal). -/
def averageComponent (n K M : ℕ) (a u : ℝ) (aug : Augmentation n K) (C : Finset (Fin n)) (labels : Labels n) : ℝ :=
  (componentDensity true true n K M a u aug C labels+componentDensity true false n K M a u aug C labels)/2

/-- Bernmeasure: the displayed mathematical construction or bound. This statement assumes [the e parameter](hyp:e), [the x parameter](hyp:x). [This is the stated defined object](goal). -/
def bernMeasure (e : Nuisance) (x : unitInterval) : Measure Bool :=
  ENNReal.ofReal (e x) • Measure.dirac true+ENNReal.ofReal (1-e x) • Measure.dirac false

/-- Signed binary law realizing a continuous mean triple. This statement assumes [the m parameter](hyp:m), [the x parameter](hyp:x). [This is the stated defined object](goal). -/
def binaryArmMeasure (m : Nuisance) (x : unitInterval) : Measure ℝ :=
  ENNReal.ofReal ((1+m x)/2) • Measure.dirac (1:ℝ)+ENNReal.ofReal ((1-m x)/2) • Measure.dirac (-1:ℝ)

/-- [Capped signed-binary critical radius](goal). \(r_n^{*,\mathrm{bin}}(w)=\inf(\{r\in(0,D_w^{\mathrm{bin}}):B_n^{\mathrm{bin}}(w,r)\le1/10\}\cup\{D_w^{\mathrm{bin}}\})\). This statement assumes [the n parameter](hyp:n), [the w parameter](hyp:w). -/
-- @node: def:binary-radius
def binaryCriticalRadius (w : Smooth3) : ℝ := cappedRadius (maxDistBinary w) (binaryTestingRisk n w) -- @realizes rstarbin(binary capped radius)

/-- Replace only the outcome coordinate by a sign. This statement assumes [the o parameter](hyp:o), [the b parameter](hyp:b). [This is the stated defined object](goal). -/
-- @node: binaryRecordAtom
def binaryRecordAtom (o : Record) (b : Bool) : Record := (X o, A o, signVal b)

/-- Binarytentprior: the displayed mathematical construction or bound. This statement assumes [the ν parameter](hyp:ν), [the n parameter](hyp:n), [the w parameter](hyp:w). [This is the stated defined object](goal). -/
def binaryTentPrior (ν : Bool) (n : ℕ) (w : Smooth3) : FinitePrior :=
  finitePriorOf (fun _ : Fin (tentRank n (Params.ofBounded w)/2) → Bool => (2:ℝ)^(-(tentRank n (Params.ofBounded w)/2:ℤ))) (binaryTentLaw ν n w)

/-- [Signed-binary full-record decision problem](goal). \(B_n^{\mathrm{bin}}(w,r)=\inf_{\phi:\sup_{P\in H_0^{\mathrm{bin}}(w)}\mathsf R_n(P,\phi)\le1/10}\sup_{P\in\mathcal M^{\mathrm{bin}}_w:d(P)\ge r}\{1-\mathsf R_n(P,\phi)\},\quad n\ge2,\ w\in\mathcal W,\ 0<r<D_w^{\mathrm{bin}}\). This statement assumes [the n parameter](hyp:n), [the w parameter](hyp:w), [the r parameter](hyp:r). -/
-- @node: def:binary-risk
def binaryTestingRisk (n : ℕ) (w : Smooth3) (r : ℝ) : ℝ := testingRiskOn n r {law | InBinaryNull w law} {law | InBinaryModel w law} -- @realizes Bbin(binary risk)

/-- Use the separate bounded copula tuning or signed-binary paired-tent family. This statement assumes [the ν parameter](hyp:ν), [the n parameter](hyp:n), [the w parameter](hyp:w). [This is the stated defined object](goal). [Defining clause 1](step:1) is used. [Defining clause 2](step:2) is used. -/
def boundedConversePrior (ν : Bool) (n : ℕ) (w : Smooth3) : FinitePrior :=
  let v := Params.ofBounded w
  if roughBranch n v then copulaPrior ν v (roughK n v) (roughM n v)
    ((roughK n v:ℝ)^(-v.α)/16) (2*(roughK n v:ℝ)^(-v.β)/256) (1/2) 1
  else binaryTentPrior ν n w

/-- [Capped bounded critical radius](goal). \(r_n^{*,\mathrm b}(w)=\inf(\{r\in(0,D_w^{\mathrm b}):B_n^{\mathrm b}(w,r)\le1/10\}\cup\{D_w^{\mathrm b}\})\). This statement assumes [the n parameter](hyp:n), [the w parameter](hyp:w). -/
-- @node: def:bounded-radius
def boundedCriticalRadius (w : Smooth3) : ℝ := cappedRadius (maxDistBounded w) (boundedTestingRisk n w) -- @realizes rstarbound(bounded capped radius)

/-- [Bounded full-record decision problem](goal). \(B_n^{\mathrm b}(w,r)=\inf_{\phi:\sup_{P\in H_0^{\mathrm b}(w)}\mathsf R_n(P,\phi)\le1/10}\sup_{P\in\mathcal M^{\mathrm b}_w:d(P)\ge r}\{1-\mathsf R_n(P,\phi)\},\quad n\ge2,\ w\in\mathcal W,\ 0<r<D_w^{\mathrm b}\). This statement assumes [the n parameter](hyp:n), [the w parameter](hyp:w), [the r parameter](hyp:r). -/
-- @node: def:bounded-risk
def boundedTestingRisk (n : ℕ) (w : Smooth3) (r : ℝ) : ℝ := testingRiskOn n r {law | InBoundedNull w law} {law | InBoundedModel w law} -- @realizes Bbound(bounded risk)

/-- Remove the mean and both singleton projections from the pair kernel. This statement assumes [the P parameter](hyp:P), [the g parameter](hyp:g), [the x parameter](hyp:x), [the y parameter](hyp:y). [This is the stated defined object](goal). -/
def canonicalProjection (P : Measure Ω) (g : Ω → Ω → ℝ) (x y : Ω) : ℝ :=
  g x y-pairMean P g-singletonProjection P g x-singletonProjection P g y

/-- Subtract the constant-coordinate projection of a histogram vector. This statement assumes [the z parameter](hyp:z). [This is the stated defined object](goal). -/
def centerVec {J : ℕ} (z : Vec J) : Vec J :=
  z-((∑ j : Fin J, z j)/(J:ℝ)) • WithLp.toLp 2 (fun _ : Fin J => (1:ℝ))

/-- Paired adjacent coarse tents carry opposite values of the same fair coarse sign. This statement assumes [the M parameter](hyp:M), [the σ parameter](hyp:σ), [the x parameter](hyp:x). [This is the stated defined object](goal). -/
def coarseTent (M : ℕ) (σ : Fin (M/2) → Bool) (x : ℝ) : ℝ :=
  ∑ j : Fin (M/2), signVal (σ j)*(tentBase ((M:ℝ)*x-2*j.val)-tentBase ((M:ℝ)*x-(2*j.val+1)))

/-- Combine uniform covariates, independent mark indicators and fair boundary disclosure. This statement assumes [the n parameter](hyp:n), [the K parameter](hyp:K), [the M parameter](hyp:M), [the ε parameter](hyp:ε). [This is the stated defined object](goal). -/
def commonAugmentation (n K M : ℕ) (ε : ℝ) : Measure (Augmentation n K) :=
  (Measure.pi fun _ : Fin n => design).prod ((Measure.pi fun _ : Fin n => markFlagLaw ε).prod (disclosureLaw K M))

/-- Average squared even discrepancy divided by the actual null component density over every fair label. This statement assumes [the n parameter](hyp:n), [the K parameter](hyp:K), [the M parameter](hyp:M), [the a parameter](hyp:a), [the u parameter](hyp:u), [the aug parameter](hyp:aug), [the C parameter](hyp:C). [This is the stated defined object](goal). -/
def componentEvenActivity (n K M : ℕ) (a u : ℝ) (aug : Augmentation n K) (C : Finset (Fin n)) : ℝ :=
  (4:ℝ)^(-(n:ℤ))*∑ labels : Labels n, evenDiscrepancy n K M a u aug C labels^2/nullComponent n K M a u aug C labels

/-- Average squared odd discrepancy divided by the intermediate component density over every fair label. This statement assumes [the n parameter](hyp:n), [the K parameter](hyp:K), [the M parameter](hyp:M), [the a parameter](hyp:a), [the u parameter](hyp:u), [the aug parameter](hyp:aug), [the C parameter](hyp:C). [This is the stated defined object](goal). -/
def componentOddActivity (n K M : ℕ) (a u : ℝ) (aug : Augmentation n K) (C : Finset (Fin n)) : ℝ :=
  (4:ℝ)^(-(n:ℤ))*∑ labels : Labels n, oddDiscrepancy n K M a u aug C labels^2/averageComponent n K M a u aug C labels

/-- A component contains all observations connected by occupied neighbouring fine intervals sharing an undisclosed coefficient. This statement assumes [the n parameter](hyp:n), [the K parameter](hyp:K), [the M parameter](hyp:M), [the aug parameter](hyp:aug), [the i parameter](hyp:i). [This is the stated defined object](goal). -/
def componentOf (n K M : ℕ) (aug : Augmentation n K) (i : Fin n) : Finset (Fin n) :=
  Finset.univ.filter (fun j => Relation.ReflTransGen (componentEdge n K M aug) i j)

entries.statement:
∀ (n K M : ℕ) (u : ℝ) (aug : CausalSmith.Stat.FinitepHomogeneityDensegamma.Augmentation n K) (C : Finset (Fin n)) (labels : CausalSmith.Stat.FinitepHomogeneityDensegamma.Labels n) (i : Fin n),
  have D := fun ν s => ∑ p, CausalSmith.Stat.FinitepHomogeneityDensegamma.conditionalPairWeight ν K M (fun x => s) aug.2.2 p * ((∏ j ∈ C.erase i, CausalSmith.Stat.FinitepHomogeneityDensegamma.labelDensity ν K M 0 u (fun x => s, p) (aug.1 j) (aug.2.1 j) (labels j)) * CausalSmith.Stat.FinitepHomogeneityDensegamma.labelPropensitySlope ν K M u (fun x => s, p) (aug.1 i) (aug.2.1 i) (labels i));
  D true true + D true false = 2 * D false false

entries.source:
/-- Collect distinct observation components of the complete augmented design. This statement assumes [the n parameter](hyp:n), [the K parameter](hyp:K), [the M parameter](hyp:M), [the aug parameter](hyp:aug). [This is the stated defined object](goal). -/
def components (n K M : ℕ) (aug : Augmentation n K) : Finset (Finset (Fin n)) :=
  Finset.univ.image (componentOf n K M aug)

entries.statement:
∀ (K M : ℕ) (δ : CausalSmith.Stat.FinitepHomogeneityDensegamma.Disclosure K) (F H : (Fin (K + 1) → Bool) → ℝ) (G : Fin (K + 1) → (Fin (K + 1) → Bool) → ℝ) (t : ℝ),
  have V := fun ν s p => (F fun i => (p i).2) + ∑ j, (G j fun i => (p i).2) * CausalSmith.Stat.FinitepHomogeneityDensegamma.signVal (p j).1 + (if ν = true then if s = true then t else -t else 0) * H fun i => (p i).2;
  ∑ p, CausalSmith.Stat.FinitepHomogeneityDensegamma.conditionalPairWeight true K M (fun x => true) δ p * V true true p + ∑ p, CausalSmith.Stat.FinitepHomogeneityDensegamma.conditionalPairWeight true K M (fun x => false) δ p * V true false p = 2 * ∑ p, CausalSmith.Stat.FinitepHomogeneityDensegamma.conditionalPairWeight false K M (fun x => false) δ p * V false false p

∀ (K M : ℕ) (δ : CausalSmith.Stat.FinitepHomogeneityDensegamma.Disclosure K) (F H : (Fin (K + 1) → Bool) → ℝ) (G : Fin (K + 1) → (Fin (K + 1) → Bool) → ℝ) (t : ℝ),
  have V := fun ν s p => (F fun i => (p i).1) + ∑ j, (G j fun i => (p i).1) * CausalSmith.Stat.FinitepHomogeneityDensegamma.signVal (p j).2 + (if ν = true then if s = true then t else -t else 0) * H fun i => (p i).1;
  ∑ p, CausalSmith.Stat.FinitepHomogeneityDensegamma.conditionalPairWeight true K M (fun x => true) δ p * V true true p + ∑ p, CausalSmith.Stat.FinitepHomogeneityDensegamma.conditionalPairWeight true K M (fun x => false) δ p * V true false p = 2 * ∑ p, CausalSmith.Stat.FinitepHomogeneityDensegamma.conditionalPairWeight false K M (fun x => false) δ p * V false false p

