/-- Mix the complete iid records under the branchwise converse prior. This statement assumes [the ν parameter](hyp:ν), [the n parameter](hyp:n), [the v parameter](hyp:v). [This is the stated defined object](goal). -/
def converseMixture (ν : Bool) (n : ℕ) (v : Params) : Measure (Dataset n) :=
  priorMixture n (conversePrior ν n v) -- @realizes MixNull(null iid mixture) @realizes MixAlt(alternative iid mixture)

/-- [Tail-essential normalized full-record converse handle](goal). Select the explicit priors for valid tuples and n ≥ 2. When Fphase < 1 and n ≥ Nlow, use K = leastPow2Ge(Hfine n^(2/Dp)), M = 2^floor(log₂(K^(S/γ)/16)), a = K^(−α)/16, u = 1/16, ε = 16^(−1/q) K^(−β/q) and L = ε^(−1/p). Otherwise use the paired-tent priors with N = 2 ceil(n^(2q/(2γ+q))), h = 1/N, ε = h^(γ/q) and L = h^(−γ/(p−1)), control kernel δ₀, and treated masses ε(1 ± νκgσ)/2 at ±L and 1 − ε at zero. Mix the entire iid record laws. Legality, separation, mixture distance and divergence are proved by the converse theorem. This statement assumes [the ν parameter](hyp:ν), [the n parameter](hyp:n), [the v parameter](hyp:v). -/
-- @node: def:converse-handle
def conversePrior (ν : Bool) (n : ℕ) (v : Params) : FinitePrior :=
  if roughBranch n v then copulaPrior ν v (roughK n v) (roughM n v)
    ((roughK n v:ℝ)^(-v.α)/16) (1/16) (rarity n v) (magnitude n v)
  else tentPrior ν n v -- @realizes piNull(null branch at nu=0) @realizes piAlt(alternative branch at nu=1)

/-- Insert every finite coefficient draw into the complete-record table construction. This statement assumes [the ν parameter](hyp:ν), [the v parameter](hyp:v), [the K parameter](hyp:K), [the M parameter](hyp:M), [the a parameter](hyp:a), [the u parameter](hyp:u), [the ε parameter](hyp:ε), [the L parameter](hyp:L), [the idx parameter](hyp:idx). [This is the stated defined object](goal). -/
def copulaLaw (ν : Bool) (v : Params) (K M : ℕ) (a u ε L : ℝ) (idx : CopulaIndex K M) : ObservedLaw :=
  tableObservedLaw (copulaXi K M a idx) (copulaUpsilon K M u idx) (copulaZeta ν K M a u idx) ε L

/-- Mix every sign-copula support law at the original sample size. This statement assumes [the ν parameter](hyp:ν), [the n parameter](hyp:n), [the v parameter](hyp:v), [the K parameter](hyp:K), [the M parameter](hyp:M), [the a parameter](hyp:a), [the u parameter](hyp:u), [the ε parameter](hyp:ε), [the L parameter](hyp:L). [This is the stated defined object](goal). -/
def copulaMixture (ν : Bool) (n : ℕ) (v : Params) (K M : ℕ) (a u ε L : ℝ) : Measure (Dataset n) :=
  priorMixture n (copulaPrior ν v K M a u ε L)

/-- The correction cancels the singleton sign-copula interaction through the squared-frame interpolated tent. This statement assumes [the ν parameter](hyp:ν), [the K parameter](hyp:K), [the M parameter](hyp:M), [the a parameter](hyp:a), [the u parameter](hyp:u), [the idx parameter](hyp:idx), [the x parameter](hyp:x). [This is the stated defined object](goal). -/
def copulaT (ν : Bool) (K M : ℕ) (a u : ℝ) (idx : CopulaIndex K M) (x : unitInterval) : ℝ :=
  -(if ν then 1 else 0)*a*u*kappa0/(1-a^2)*smoothedTent K M idx.1 x

/-- Combine fair coarse signs with the conditionally independent sign-copula coefficient draws. This statement assumes [the ν parameter](hyp:ν), [the K parameter](hyp:K), [the M parameter](hyp:M), [the idx parameter](hyp:idx). [This is the stated defined object](goal). -/
def copulaWeight (ν : Bool) (K M : ℕ) (idx : CopulaIndex K M) : ℝ :=
  (1/2:ℝ)^(M/2)*∏ i : Fin (K+1), pairWeight ν (coarseTent M idx.1 ((i:ℝ)/K)) (idx.2 i).1 (idx.2 i).2

/-- The table interaction combines the coordinate product and the corrected deterministic effect term. This statement assumes [the ν parameter](hyp:ν), [the K parameter](hyp:K), [the M parameter](hyp:M), [the a parameter](hyp:a), [the u parameter](hyp:u), [the idx parameter](hyp:idx), [the x parameter](hyp:x). [This is the stated defined object](goal). -/
def copulaZeta (ν : Bool) (K M : ℕ) (a u : ℝ) (idx : CopulaIndex K M) (x : unitInterval) : ℝ :=
  copulaXi K M a idx x*copulaUpsilon K M u idx x+copulaT ν K M a u idx x*(1-copulaXi K M a idx x^2)

/-- The only rational amplitude factor in the marked-record copula correction, with `t` equal to the squared propensity frame field. This statement assumes [the t parameter](hyp:t), [the a parameter](hyp:a). [This is the stated defined object](goal). -/
-- @node: correctionFactor
def correctionFactor (t a : ℝ) : ℝ := a * (1 - a^2*t) / (1 - a^2)

/-- [Capped critical radius with sentinel](goal). \(r_n^*(v)=\inf\bigl(\{r\in(0,D_v):B_n(v,r)\le1/10\}\cup\{D_v\}\bigr)\). This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v). -/
-- @node: def:critical-radius
def criticalRadius : ℝ := cappedRadius (maxDist v) (testingRisk n v) -- @realizes rstar(capped infimum)

/-- The increment singleton budget combines primitive approximation and clipping remainder. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v), [the j parameter](hyp:j). [This is the stated defined object](goal). -/
def dLev (n : ℕ) (v : Params) (j : ℕ) : ℝ :=
  110*(ledgerR n v (j-1):ℝ)^(-min v.α (min v.β v.γ))+20*ledgerT n v j^(1-v.p)

/-- Literal deterministic arm kernels for the two public nonemptiness witnesses. This statement assumes [the e parameter](hyp:e), [the m0 parameter](hyp:m0), [the τ parameter](hyp:τ). [This is the stated defined object](goal). -/
def deterministicRecord (e m0 τ : Nuisance) : Measure Record :=
  design ⊗ₘ recordKernel e e.continuous.measurable (fun a => (if a then deterministicArm (m0+τ) else deterministicArm m0))

/-- Reveal precisely the coefficient pairs at coarse boundaries. This statement assumes [the K parameter](hyp:K), [the M parameter](hyp:M), [the pairs parameter](hyp:pairs). [This is the stated defined object](goal). -/
def disclose (K M : ℕ) (pairs : CoefficientPairs K) : Disclosure K :=
  fun i => if boundaryNode K M i then some (pairs i) else none

/-- Push fair fine-node coefficient pairs through the boundary-only disclosure map. This statement assumes [the K parameter](hyp:K), [the M parameter](hyp:M). [This is the stated defined object](goal). -/
def disclosureLaw (K M : ℕ) : Measure (Disclosure K) :=
  ∑ pairs : CoefficientPairs K, ENNReal.ofReal ((4:ℝ)^(-(K+1:ℤ))) • Measure.dirac (disclose K M pairs)

/-- Equivalence classes retain precisely Borel versions equal almost everywhere. This statement assumes [the f parameter](hyp:f). [This is the stated defined object](goal). -/
def eqClass (f : unitInterval → ℝ) : Set (unitInterval → ℝ) :=
  {g | Measurable g ∧ g =ᵐ[design] f} -- @realizes EqClass(Borel a.e. equivalence)

/-- Canonically enumerate the coordinates in one deterministic evaluation block. This statement assumes [the n parameter](hyp:n), [the b parameter](hyp:b). [This is the stated defined object](goal). -/
def evalBlockEquiv (n : ℕ) (b : Bool) : Fin (blockSize n) ≃ {i // i ∈ evalBlock n b} :=
  (Finset.orderIsoOfFin (evalBlock n b) (evalBlock_card n b)).toEquiv

/-- The even discrepancy subtracts the actual null density from the sign-averaged component density. This statement assumes [the n parameter](hyp:n), [the K parameter](hyp:K), [the M parameter](hyp:M), [the a parameter](hyp:a), [the u parameter](hyp:u), [the aug parameter](hyp:aug), [the C parameter](hyp:C), [the labels parameter](hyp:labels). [This is the stated defined object](goal). -/
def evenDiscrepancy (n K M : ℕ) (a u : ℝ) (aug : Augmentation n K) (C : Finset (Fin n)) (labels : Labels n) : ℝ :=
  averageComponent n K M a u aug C labels-nullComponent n K M a u aug C labels

/-- Extract one deterministic evaluation block as a sample indexed by its block size. This statement assumes [the n parameter](hyp:n), [the b parameter](hyp:b), [the data parameter](hyp:data). [This is the stated defined object](goal). -/
def extractEvalBlock (n : ℕ) (b : Bool) (data : Dataset n) : Fin (blockSize n) → Record :=
  fun i => data (evalBlockEquiv n b i).1

/-- Turn a finite fair-label density into the corresponding probability-table measure. This statement assumes [the n parameter](hyp:n), [the density parameter](hyp:density). [This is the stated defined object](goal). -/
def fairLabelMeasure (n : ℕ) (density : Labels n → ℝ) : Measure (Labels n) :=
  ∑ labels : Labels n, ENNReal.ofReal ((4:ℝ)^(-(n:ℤ))*density labels) • Measure.dirac labels

/-- Enumerate a finite weighted family through its finite-index equivalence. This statement assumes [the weight parameter](hyp:weight), [the laws parameter](hyp:laws). [This is the stated defined object](goal). -/
def finitePriorOf {ι : Type} [Fintype ι] (weight : ι → ℝ) (laws : ι → ObservedLaw) : FinitePrior :=
  ⟨Fintype.card ι,(fun i => weight ((Fintype.equivFin ι).symm i)),(fun i => laws ((Fintype.equivFin ι).symm i))⟩

/-- [Finite-overlap smooth-field tool](goal). The public frame object consists only of the displayed cosine/sine coordinates and their finite coefficient fields. Copula coupling, coarse opposite tents, marked tables and mixture integration are defined separately by `copulaPrior`. For positive rank K, the two active coordinates on each covariate cell are cos(π(Kx−i)/2) and sin(π(Kx−i)/2). This statement assumes [the K parameter](hyp:K), [the i parameter](hyp:i), [the x parameter](hyp:x). -/
-- @node: def:frame-handle
def frameCoord (K : ℕ) (i : Fin (K+1)) (x : ℝ) : ℝ :=
  if (i:ℝ)/K ≤ x ∧ x ≤ ((i:ℝ)+1)/K then Real.cos (Real.pi*((K:ℝ)*x-i)/2)
  else if 0 < i.val ∧ ((i:ℝ)-1)/K ≤ x ∧ x ≤ (i:ℝ)/K then Real.sin (Real.pi*((K:ℝ)*x-((i:ℝ)-1))/2)
  else 0 -- @realizes Frame(explicit cosine/sine finite-overlap frame)

/-- Average the clipped treated single-record feature vectors within the selected deterministic block. This statement assumes [the n parameter](hyp:n), [the b parameter](hyp:b), [the J parameter](hyp:J), [the T parameter](hyp:T), [the data parameter](hyp:data). [This is the stated defined object](goal). -/
def hIntercept (n : ℕ) (b : Bool) (J : ℕ) (T : ℝ) (data : Dataset n) : Vec J :=
  if n < 4 then 0 else (blockSize n : ℝ)⁻¹ • ∑ i ∈ evalBlock n b,
    (treatment (data i)*clipY T (Y (data i))) • featureMap J (X (data i))

/-- Average the treatment-weighted feature vectors within the selected block. This statement assumes [the n parameter](hyp:n), [the b parameter](hyp:b), [the J parameter](hyp:J), [the data parameter](hyp:data). [This is the stated defined object](goal). -/
def hTreatment (n : ℕ) (b : Bool) (J : ℕ) (data : Dataset n) : Vec J :=
  if n < 4 then 0 else (blockSize n : ℝ)⁻¹ • ∑ i ∈ evalBlock n b,
    treatment (data i) • featureMap J (X (data i))

/-- Multiply the normalized independent sign-averaged component densities. This statement assumes [the n parameter](hyp:n), [the K parameter](hyp:K), [the M parameter](hyp:M), [the a parameter](hyp:a), [the u parameter](hyp:u), [the aug parameter](hyp:aug), [the labels parameter](hyp:labels). [This is the stated defined object](goal). -/
def intermediateDensity (n K M : ℕ) (a u : ℝ) (aug : Augmentation n K) (labels : Labels n) : ℝ :=
  ∏ C ∈ components n K M aug, averageComponent n K M a u aug C labels

/-- The clipped inverse-propensity score uses the two observed treatment arms. This statement assumes [the f parameter](hyp:f), [the T parameter](hyp:T), [the o parameter](hyp:o). [This is the stated defined object](goal). -/
def ipwScore (f : Nuisance) (T : ℝ) (o : Record) : ℝ :=
  treatment o*clipY T (Y o)/clipProp f (X o)-(1-treatment o)*clipY T (Y o)/(1-clipProp f (X o))

/-- The untruncated inverse-propensity score targets the original conditional mean effect. This statement assumes [the f parameter](hyp:f), [the o parameter](hyp:o). [This is the stated defined object](goal). -/
def ipwUntruncated (f : Nuisance) (o : Record) : ℝ :=
  treatment o*Y o/clipProp f (X o)-(1-treatment o)*Y o/(1-clipProp f (X o))

/-- The bias ledger retains interaction approximation, main tail bias and every increment tail contribution. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v). [This is the stated defined object](goal). -/
def ledgerBias (n : ℕ) (v : Params) : ℝ :=
  if n < 4 then 0 else 400*(ledgerK n v:ℝ)^(-sumReg v)+20*ledgerT0 n v^(1-v.p)+
  if singleBranch v then 0 else 10*∑ j : Fin (ledgerL n v), aLev n v (j.val+1)*ledgerT n v (j.val+1)^(1-v.p) -- @realizes Bias(public bias ledger)

/-- Ledgercoeff: the displayed mathematical construction or bound. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v), [the b parameter](hyp:b), [the r parameter](hyp:r), [the data parameter](hyp:data). [This is the stated defined object](goal). -/
def ledgerCoeff (n : ℕ) (v : Params) (b r : Bool) (data : Dataset n) : Vec (ledgerM n v) :=
  if r then ledgerScore n v b 0 data-ledgerScore n v b 1 data else ledgerScore n v b 0 data

/-- The total covariance budget combines the linear and canonical ledgers with their exact block normalizations. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v). [This is the stated defined object](goal). -/
def ledgerCov (n : ℕ) (v : Params) : ℝ :=
  if n < 4 then 0 else ledgerL1 n v^2/(blockSize n:ℝ)+2*ledgerL2 n v^2/((blockSize n:ℝ)*((blockSize n:ℝ)-1)) -- @realizes Covbound(public covariance ledger)

/-- Dyadically round twice the squared bias plus the dimension-weighted covariance cutoff. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v). [This is the stated defined object](goal). -/
def ledgerCutoff (n : ℕ) (v : Params) : ℝ :=
  if n < 4 then 0 else dyadUp (2*ledgerBias n v^2+2^16*Real.sqrt (ledgerM n v)*ledgerCov n v) -- @realizes Cutoff(rounded rejection threshold)

/-- The linear covariance ledger sums the main and all increment singleton contributions. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v). [This is the stated defined object](goal). -/
def ledgerL1 (n : ℕ) (v : Params) : ℝ :=
  if n < 4 then 0 else 16*Real.sqrt (ledgerV0 n v)+
  if singleBranch v then 0 else 8*∑ j : Fin (ledgerL n v), (dLev n v (j.val+1)+aLev n v (j.val+1)*Real.sqrt (ledgerV n v (j.val+1)))

/-- Reject when the finite profiled minimum strictly exceeds the public cutoff; the small-sample branch returns zero. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v), [the z parameter](hyp:z). [This is the stated defined object](goal). -/
def ledgerRule (n : ℕ) (v : Params) (z : Experiment n) : ℝ :=
  if n < 4 then 0 else if ledgerCutoff n v < profiledMin (ledgerScore n v) z.1 then 1 else 0

/-- Select the packaged scalar kernel belonging to the active public score branch. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v), [the r parameter](hyp:r), [the u parameter](hyp:u). [This is the stated defined object](goal). -/
def ledgerScalarKernel (n : ℕ) (v : Params) (r : Bool) (u : Vec (ledgerM n v)) :
    Record → Record → ℝ :=
  if singleBranch v then singleScalarKernel (ledgerM n v) (ledgerK n v)
      (ledgerT0 n v) r u
  else multiresScalarKernel (ledgerM n v) (ledgerL n v) (ledgerT0 n v)
      (fun j => ledgerT n v (j.val+1)) r u

/-- Subtract the initial correction and every level-specific correction from the observed single-record score. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v), [the b parameter](hyp:b), [the c parameter](hyp:c), [the data parameter](hyp:data). [This is the stated defined object](goal). -/
def ledgerScore (n : ℕ) (v : Params) (b : Bool) (c : ℝ) (data : Dataset n) : Vec (ledgerM n v) :=
  if n < 4 then 0 else if singleBranch v then
    hScore n b (ledgerM n v) (ledgerT0 n v) c data-uScore n b (ledgerM n v) (projKernel (ledgerK n v)) (ledgerT0 n v) c data
  else multiresScore n b (ledgerM n v) (ledgerL n v) (ledgerT0 n v) (fun j => ledgerT n v (j.val+1)) c data -- @realizes Zscore(explicit multiresolution score)

/-- Each increment cutoff is dyadically rounded after truncation to the public admissible interval. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v), [the j parameter](hyp:j). [This is the stated defined object](goal). -/
def ledgerT (n : ℕ) (v : Params) (j : ℕ) : ℝ :=
  if n < 4 then 1 else dyadUp (max 1 (min (ledgerA n v ^ (-1/(v.p-1)))
    (((ledgerR n v j:ℝ)^(-v.α)/(ledgerA n v*((ledgerR n v j:ℝ)/ledgerK n v)^lam0 v))^(1/(v.p-1)))))

/-- The at-most-two-dimensional population affine profile subspace. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v), [the law parameter](hyp:law). [This is the stated defined object](goal). -/
def ledgerThetaSpan (n : ℕ) (v : Params) (law : ObservedLaw) :
    Submodule ℝ (Vec (ledgerM n v)) :=
  Submodule.span ℝ {ledgerTheta n v law 0,
    ledgerTheta n v law 0-ledgerTheta n v law 1}

/-- Select the moment-normalized rough mark size or the paired-tent mark size. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v). [This is the stated defined object](goal). -/
def magnitude (n : ℕ) (v : Params) : ℝ :=
  if roughBranch n v then rarity n v^(-1/v.p) else tentMagnitude n v -- @realizes magnitude(branchwise derived mark size)

/-- Scalarize the one-record part of a multiresolution affine coefficient. This statement assumes [the J parameter](hyp:J), [the T0 parameter](hyp:T0), [the r parameter](hyp:r), [the u parameter](hyp:u), [the o parameter](hyp:o). [This is the stated defined object](goal). -/
def multiresScalarSingle (J : ℕ) (T0 : ℝ) (r : Bool) (u : Vec J) (o : Record) : ℝ :=
  inner ℝ u (multiresSingleKernel J T0 r o)

/-- The two single-record coefficient kernels, with true denoting the treatment coefficient. This statement assumes [the J parameter](hyp:J), [the T0 parameter](hyp:T0), [the r parameter](hyp:r), [the o parameter](hyp:o). [This is the stated defined object](goal). -/
def multiresSingleKernel (J : ℕ) (T0 : ℝ) (r : Bool) (o : Record) : Vec J :=
  (treatment o*(if r then 1 else clipY T0 (Y o))) • featureMap J (X o)

/-- The null component density averages the uncoupled coefficient law. This statement assumes [the n parameter](hyp:n), [the K parameter](hyp:K), [the M parameter](hyp:M), [the a parameter](hyp:a), [the u parameter](hyp:u), [the aug parameter](hyp:aug), [the C parameter](hyp:C). [This is the stated defined object](goal). -/
def nullComponent (n K M : ℕ) (a u : ℝ) (aug : Augmentation n K) (C : Finset (Fin n)) : Labels n → ℝ :=
  componentDensity false false n K M a u aug C

/-- Multiply the actual independent null component densities. This statement assumes [the n parameter](hyp:n), [the K parameter](hyp:K), [the M parameter](hyp:M), [the a parameter](hyp:a), [the u parameter](hyp:u), [the aug parameter](hyp:aug), [the labels parameter](hyp:labels). [This is the stated defined object](goal). -/
def nullConditionalDensity (n K M : ℕ) (a u : ℝ) (aug : Augmentation n K) (labels : Labels n) : ℝ :=
  ∏ C ∈ components n K M aug, nullComponent n K M a u aug C labels

/-- [The occ Cell object](goal) is defined from [the K parameter](hyp:K), [the hK parameter](hyp:hK), [the x parameter](hyp:x). -/
def occCell (K : ℕ) (hK : 0 < K) (x : unitInterval) : Fin K :=
  ⟨fineIndex K x, by simp only [fineIndex]; omega⟩

/-- The odd discrepancy is half the difference of the two coarse-sign component densities. This statement assumes [the n parameter](hyp:n), [the K parameter](hyp:K), [the M parameter](hyp:M), [the a parameter](hyp:a), [the u parameter](hyp:u), [the aug parameter](hyp:aug), [the C parameter](hyp:C), [the labels parameter](hyp:labels). [This is the stated defined object](goal). -/
def oddDiscrepancy (n K M : ℕ) (a u : ℝ) (aug : Augmentation n K) (C : Finset (Fin n)) (labels : Labels n) : ℝ :=
  (componentDensity true true n K M a u aug C labels-componentDensity true false n K M a u aug C labels)/2

