have m := ∫ (data : Fin n → CausalSmith.Stat.FinitepHomogeneityDensegamma.Record), CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleBlockVec n v law.e false data ∂MeasureTheory.Measure.pi fun x => law.P;
have W := fun data => inner ℝ (CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleBlockVec n v law.e false data) (CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleBlockVec n v law.e true data);
(MeasureTheory.Measure.pi fun x => law.P).real {data | 16 * (√(CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleCov n v) * ‖m‖ + √↑(CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleJ n v) * CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleCov n v) < |W data - ‖m‖ ^ 2|} ≤ 1e-2

