have μ := ∫ (data : Fin n → CausalSmith.Stat.FinitepHomogeneityDensegamma.Record), CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleBlockVec n v law.e false data ∂MeasureTheory.Measure.pi fun x => law.P;
have W := fun data => inner ℝ (CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleBlockVec n v law.e false data) (CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleBlockVec n v law.e true data);
(∀ (b : Bool) (u : CausalSmith.Stat.FinitepHomogeneityDensegamma.Vec (CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleJ n v)), MeasureTheory.MemLp (fun data => inner ℝ u (CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleBlockVec n v law.e b data)) 2 (MeasureTheory.Measure.pi fun x => law.P) ∧ ProbabilityTheory.variance (fun data => inner ℝ u (CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleBlockVec n v law.e b data)) (MeasureTheory.Measure.pi fun x => law.P) ≤ CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleCov n v * ‖u‖ ^ 2) ∧ (∫ (data : Fin n → CausalSmith.Stat.FinitepHomogeneityDensegamma.Record), W data ∂MeasureTheory.Measure.pi fun x => law.P) = ‖μ‖ ^ 2 ∧ ProbabilityTheory.variance W (MeasureTheory.Measure.pi fun x => law.P) ≤ 2 * CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleCov n v * ‖μ‖ ^ 2 + ↑(CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleJ n v) * CausalSmith.Stat.FinitepHomogeneityDensegamma.oracleCov n v ^ 2

entries.source:
/-- Average the kernel over every ordered distinct pair in a finite sample. This statement assumes [the s parameter](hyp:s), [the g parameter](hyp:g), [the data parameter](hyp:data). [This is the stated defined object](goal). -/
def orderedPairAverage (s : ℕ) (g : Ω → Ω → ℝ) (data : Fin s → Ω) : ℝ :=
  ((s:ℝ)*((s:ℝ)-1))⁻¹*∑ i : Fin s, ∑ j ∈ Finset.univ.erase i, g (data i) (data j)

/-- The component is contained within one coarse-sign pair. This statement assumes [the M parameter](hyp:M), [the aug parameter](hyp:aug), [the C parameter](hyp:C). [This is the stated defined object](goal). -/
def pairIndex {n K : ℕ} (M : ℕ) (aug : Augmentation n K) (C : Finset (Fin n)) : ℕ :=
  C.sup (fun i => fineIndex M (aug.1 i)/2)

/-- The treated row is unchanged; the control kernel is identically the point mass at zero. This statement assumes [the r parameter](hyp:r), [the ε parameter](hyp:ε), [the L parameter](hyp:L), [the h parameter](hyp:h), [the a parameter](hyp:a). [This is the stated defined object](goal). -/
def pairedTentArm (r : unitInterval → ℝ) (ε L : ℝ)
    (h : TableValid (fun _ => 0) r r ε L) (a : Bool) : Kernel unitInterval ℝ :=
  if a then tableArm (fun _ => 0) r r ε L h true
  else Kernel.const unitInterval (Measure.dirac (0:ℝ))

/-- Mix the full original iid record laws using all finite family weights. This statement assumes [the n parameter](hyp:n), [the π parameter](hyp:π). [This is the stated defined object](goal). -/
def priorMixture (n : ℕ) (π : FinitePrior) : Measure (Dataset n) :=
  ∑ i : Fin π.1, ENNReal.ofReal (priorWeight π i) • Measure.pi (fun _ : Fin n => (priorLaw π i).P)

/-- Profileevent: the displayed mathematical construction or bound. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v), [the law parameter](hyp:law). [This is the stated defined object](goal). -/
def profileEvent (n : ℕ) (v : Params) (law : ObservedLaw) : Set (Dataset n) :=
  {data | ∀ c : ℝ, |c| ≤ 1/2 → |ledgerW n v c data-‖ledgerTheta n v law c‖^2| ≤
    128*(Real.sqrt (ledgerCov n v)*‖ledgerTheta n v law c‖+Real.sqrt (ledgerM n v)*ledgerCov n v)}

/-- [Exact uniform-design histogram tools](goal). \(I_{j,J}=[(j-1)/J,j/J)\) for \(j<J\), with \(I_{J,J}=[(J-1)/J,1]\); \(F_J(x)=(\sqrt J\,\mathbf1_{I_{j,J}}(x))_{j=1}^J\), \(\Pi_J(x,z)=\langle F_J(x),F_J(z)\rangle\), and \((\Pi_J f)(x)=\int_0^1\Pi_J(x,z)f(z)\,dz\). This statement assumes [the J parameter](hyp:J), [the x parameter](hyp:x), [the z parameter](hyp:z). -/
-- @node: def:projection
def projKernel (x z : unitInterval) : ℝ := inner ℝ (featureMap J x) (featureMap J z) -- @realizes Pi(exact histogram kernel)

/-- The two public dyadic endpoints bracketing the unrounded rejection cutoff. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v). [This is the stated defined object](goal). [Defining clause 1](step:1) is used. [Defining clause 2](step:2) is used. -/
def publicCutoffGrid (n : ℕ) (v : Params) : Finset ℝ :=
  if n < 4 then {0} else
    let x := 2*ledgerBias n v^2+2^16*Real.sqrt (ledgerM n v)*ledgerCov n v
    {(2:ℝ)^(Int.floor (Real.logb 2 x)),dyadUp x}

/-- The finite public grid containing every outcome cutoff. This statement assumes [the n parameter](hyp:n). [This is the stated defined object](goal). -/
def publicOutcomeGrid (n : ℕ) : Finset ℝ :=
  (Finset.range (Nat.ceil (Real.logb 2 (2*(blockSize n:ℝ)))+1)).image (fun j => (2:ℝ)^j)

/-- The finite public grid containing the two histogram ranks. This statement assumes [the n parameter](hyp:n). [This is the stated defined object](goal). -/
def publicRankGrid (n : ℕ) : Finset ℕ :=
  (Finset.range (Nat.ceil (Real.logb 2 (2*(blockSize n:ℝ)^2))+1)).image (fun j => 2^j)

/-- Multiply the two independent block vectors by their Euclidean inner product. This statement assumes [the score parameter](hyp:score), [the c parameter](hyp:c), [the data parameter](hyp:data). [This is the stated defined object](goal). -/
def quadStat {n J : ℕ} (score : Bool → ℝ → Dataset n → Vec J) (c : ℝ) (data : Dataset n) : ℝ :=
  inner ℝ (score false c data) (score true c data)

/-- A quadratic on the null interval is minimized at an endpoint or an admissible positive-curvature vertex. This statement assumes [the q0 parameter](hyp:q0), [the q1 parameter](hyp:q1), [the q2 parameter](hyp:q2). [This is the stated defined object](goal). [Defining clause 1](step:1) is used. [Defining clause 2](step:2) is used. [Defining clause 3](step:3) is used. -/
def quadraticMin (q0 q1 q2 : ℝ) : ℝ :=
  let ends := min (q0-q1/2+q2/4) (q0+q1/2+q2/4)
  let vertex := -q1/(2*q2)
  if 0 < q2 ∧ -1/2 ≤ vertex ∧ vertex ≤ 1/2 then min ends (q0-q1^2/(4*q2)) else ends

/-- [Matched heavy-tail versus bounded phase handle](goal). The defined object is exactly the capped-radius ratio \[\Delta_n(v)=\frac{r_n^*(v)}{r_n^{*,\mathrm b}(w)},\qquad w=(\alpha,\beta,\gamma).\] Both numerator and denominator are the capped critical radii of the original-record experiments in Definition \(\mathrm{def:testing\mbox{-}risk}\) and its bounded analogue, at the same sample size and matched smoothness tuple. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v). -/
-- @node: def:comparison-handle
def radiusRatio : ℝ := criticalRadius n v / boundedCriticalRadius n v.toSmooth3 -- @realizes Delta(matched radius ratio)

/-- Select the explicit rough-channel or paired-tent rare-mark probability. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v). [This is the stated defined object](goal). -/
def rarity (n : ℕ) (v : Params) : ℝ :=
  if roughBranch n v then (16:ℝ)^(-1/qExp v)*(roughK n v:ℝ)^(-v.β/qExp v) else tentRarity n v -- @realizes rarity(branchwise derived mark probability)

/-- [Explicit matched scales, multipliers and public thresholds](goal). For \(v\in\mathcal V\), put \[ q=(p-1)/p,\quad S=\alpha+\beta,\quad D_p=1+2\alpha+\beta/q+S/(2\gamma),\quad E_0(p)=\frac{2\gamma q}{2\gamma+q},\quad E_4(p)=\frac{2S}{D_p}, \quad F(p)=\frac{2\alpha}{p-1}+\frac\beta q+\frac S{2\gamma}, \quad E(p)=\min\{E_0(p),E_4(p)\}. \] Here arguments \(p\) in \(E_0,E_4,F,E\) retain the same \((\alpha,\beta,\gamma)\). Define \[ H_{\mathrm{fine}}=2^{40},\quad N_{\mathrm{low}}(v)=\left\lceil\max\{2,32^{D_p\gamma/(2S)}\}\right\rceil, \quad k_v=2^{-17}(2H_{\mathrm{fine}})^{-S},\quad c_0^{\mathrm e}=4^{-\gamma}/(16\sqrt3). \] The sharp scales and lower multipliers are \[ \rho_n(v)=n^{-E(p)},\qquad \rho_n^{\mathrm b}(w)=n^{-E(2)},\qquad c_v=\begin{cases} c_0^{\mathrm e},&F(p)\ge1,\\ \min\{k_v,c_0^{\mathrm e}N_{\mathrm{low}}(v)^{-(E_0(p)-E_4(p))}\},&F(p)<1, \end{cases} \qquad c_w^{\mathrm b}=c_{(2,w)}. \] Take \(C_v=C^{\mathrm{att}}_v\), \(N_v=N^{\mathrm{att}}_v\) with the fully evaluable formulas of Theorem \(\mathrm{thm:original\mbox{-}record\mbox{-}attainable\mbox{-}rate}\); take \(C_w^{\mathrm b}=C^{\mathrm{att}}_{(2,w)}\), \(N_w^{\mathrm b}=N^{\mathrm{att}}_{(2,w)}\). The rule \(\phi^*_{n,v}\) is exactly the total original-record rule of Definition \(\mathrm{def:explicit\mbox{-}score\mbox{-}ledger}\); \(\phi^{*,\mathrm b}_{n,w}\) is the same rule at tuple \((2,w)\). These definitions name scales and rules; their sharpness is a conclusion of the full-record lower and attainment proofs. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v). -/
-- @node: def:sharp-frontier-scales
def rho : ℝ := (n:ℝ)^(-Eexp v) -- @realizes rho(unknown-propensity pure power)

/-- The smallest primitive smoothness controls the geometric singleton ledger.  [the parameters and conditions in the statement](hyp:v), [the asserted mathematical result holds](goal). -/
-- @node: s0
def s0 (v : Params) : ℝ := min v.α (min v.β v.γ)

/-- The common scalar mark used by both affine coefficients: clipped outcome for the intercept and treatment for the slope. This statement assumes [the T parameter](hyp:T), [the r parameter](hyp:r), [the o parameter](hyp:o). [This is the stated defined object](goal). -/
def scoreMark (T : ℝ) (r : Bool) (o : Record) : ℝ :=
  if r then treatment o else clipY T (Y o)

/-- Scalarize the pair part of a single-correction affine coefficient. This statement assumes [the J parameter](hyp:J), [the K parameter](hyp:K), [the T0 parameter](hyp:T0), [the r parameter](hyp:r), [the u parameter](hyp:u), [the o parameter](hyp:o), [the z parameter](hyp:z). [This is the stated defined object](goal). -/
def singleScalarPair (J K : ℕ) (T0 : ℝ) (r : Bool) (u : Vec J)
    (o z : Record) : ℝ := inner ℝ u (singlePairKernel J K T0 r o z)

/-- Add a one-record summand symmetrically to a pair kernel. This statement assumes [the h parameter](hyp:h), [the g parameter](hyp:g), [the o parameter](hyp:o), [the z parameter](hyp:z). [This is the stated defined object](goal). -/
def singletonAugmentedPair (h : Record → ℝ) (g : Record → Record → ℝ)
    (o z : Record) : ℝ := (h o+h z)/2+g o z

/-- Interpolate the coarse tent values through squared smooth-frame coordinates. This statement assumes [the K parameter](hyp:K), [the M parameter](hyp:M), [the σ parameter](hyp:σ), [the x parameter](hyp:x). [This is the stated defined object](goal). -/
def smoothedTent (K M : ℕ) (σ : Fin (M/2) → Bool) (x : ℝ) : ℝ :=
  ∑ i : Fin (K+1), coarseTent M σ ((i:ℝ)/K)*frameCoord K i x^2

/-- The explicit treatment-row measures form a Borel outcome kernel. This statement assumes [the ξ parameter](hyp:ξ), [the υ parameter](hyp:υ), [the ζ parameter](hyp:ζ), [the ε parameter](hyp:ε), [the L parameter](hyp:L), [the h parameter](hyp:h), [the a parameter](hyp:a). [This is the stated defined object](goal). -/
def tableArm (ξ υ ζ : unitInterval → ℝ) (ε L : ℝ) (h : TableValid ξ υ ζ ε L) (a : Bool) : Kernel unitInterval ℝ :=
  ⟨tableArmMeasure ξ υ ζ ε L a,measurable_tableArm ξ υ ζ ε L h a⟩

/-- Normalize each treatment row of the six-category table to obtain its conditional outcome law. This statement assumes [the ξ parameter](hyp:ξ), [the υ parameter](hyp:υ), [the ζ parameter](hyp:ζ), [the ε parameter](hyp:ε), [the L parameter](hyp:L), [the a parameter](hyp:a), [the x parameter](hyp:x). [This is the stated defined object](goal). -/
def tableArmMeasure (ξ υ ζ : unitInterval → ℝ) (ε L : ℝ) (a : Bool) (x : unitInterval) : Measure ℝ :=
  ∑ h : Option Bool, ENNReal.ofReal (2*markedTable (ξ x) (υ x) (ζ x) ε (a,h)/(1+signVal a*ξ x)) • Measure.dirac (markValue L h)

/-- Mix all six conditional record categories over the uniform covariate design. This statement assumes [the ξ parameter](hyp:ξ), [the υ parameter](hyp:υ), [the ζ parameter](hyp:ζ), [the ε parameter](hyp:ε), [the L parameter](hyp:L). [This is the stated defined object](goal). -/
def tableLaw (ξ υ ζ : unitInterval → ℝ) (ε L : ℝ) : Measure Record :=
  design.bind (fun x => ∑ cat : Category, ENNReal.ofReal (markedTable (ξ x) (υ x) (ζ x) ε cat) • Measure.dirac (x,cat.1,markValue L cat.2))

/-- Retain both exact armwise clipping remainders with their propensity weights. This statement assumes [the law parameter](hyp:law), [the T parameter](hyp:T), [the x parameter](hyp:x). [This is the stated defined object](goal). -/
def tailRemainder (law : ObservedLaw) (T : ℝ) (x : unitInterval) : ℝ :=
  law.e x*(∫ y, y-clipY T y ∂law.Q true x)+(1-law.e x)*(∫ y, y-clipY T y ∂law.Q false x)

/-- Tenteffect: the displayed mathematical construction or bound. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v), [the σ parameter](hyp:σ), [the x parameter](hyp:x). [This is the stated defined object](goal). -/
def tentEffect (n : ℕ) (v : Params) (σ : Fin (tentRank n v/2) → Bool) (x : unitInterval) : ℝ :=
  kappa0*tentH n v^v.γ*coarseTent (tentRank n v) σ x

/-- Tentprior: the displayed mathematical construction or bound. This statement assumes [the ν parameter](hyp:ν), [the n parameter](hyp:n), [the v parameter](hyp:v). [This is the stated defined object](goal). -/
def tentPrior (ν : Bool) (n : ℕ) (v : Params) : FinitePrior :=
  finitePriorOf (fun _ : Fin (tentRank n v/2) → Bool => (2:ℝ)^(-(tentRank n v/2:ℤ))) (tentLaw ν n v)

/-- [Full original-record testing decision problem](goal). \(B_n(v,r)=\inf_{\phi:\ \sup_{P\in H_0(v)}\mathsf R_n(P,\phi)\le1/10}\ \sup_{P\in\mathcal M_v:\ d(P)\ge r}\{1-\mathsf R_n(P,\phi)\},\quad n\ge2,\ v\in\mathcal V,\ 0<r<D_v\). This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v), [the r parameter](hyp:r). -/
-- @node: def:testing-risk
def testingRisk : ℝ := testingRiskOn n r {law | InNull v law} {law | InModel v law} -- @realizes B(composite-null infimum supremum)

/-- The true-law mean integrates the score against the original iid record law. This statement assumes [the law parameter](hyp:law), [the score parameter](hyp:score), [the c parameter](hyp:c). [This is the stated defined object](goal). -/
def thetaVec {n J : ℕ} (law : ObservedLaw) (score : ℝ → Dataset n → Vec J) (c : ℝ) : Vec J :=
  ∫ data, score c data ∂Measure.pi (fun _ : Fin n => law.P) -- @realizes theta(true-law score mean)

/-- Exact treated-arm mean discarded by clipping, without a smoothness approximation. This statement assumes [the law parameter](hyp:law), [the T parameter](hyp:T), [the x parameter](hyp:x). [This is the stated defined object](goal). -/
def treatedTailRemainder (law : ObservedLaw) (T : ℝ) (x : unitInterval) : ℝ :=
  ∫ y, y-clipY T y ∂law.Q true x

/-- Canonical pair projection removes the mean and both singleton terms. This statement assumes [the law parameter](hyp:law), [the g parameter](hyp:g), [the o parameter](hyp:o), [the z parameter](hyp:z). [This is the stated defined object](goal). -/
def vectorCanonical {J : ℕ} (law : ObservedLaw) (g : Record → Record → Vec J) (o z : Record) : Vec J :=
  g o z-vectorPairMean law g-vectorSingleton law g o-vectorSingleton law g z

/-- Mean of a vector-valued symmetric pair kernel under the true record law. This statement assumes [the law parameter](hyp:law), [the g parameter](hyp:g). [This is the stated defined object](goal). -/
def vectorPairMean {J : ℕ} (law : ObservedLaw) (g : Record → Record → Vec J) : Vec J :=
  ∫ z : Record × Record, g z.1 z.2 ∂law.P.prod law.P

/-- True-law singleton projection of a symmetric vector-valued pair kernel. This statement assumes [the law parameter](hyp:law), [the g parameter](hyp:g), [the o parameter](hyp:o). [This is the stated defined object](goal). -/
def vectorSingleton {J : ℕ} (law : ObservedLaw) (g : Record → Record → Vec J) (o : Record) : Vec J :=
  (∫ z, g o z ∂law.P)-vectorPairMean law g
